
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(n), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='pomo-prototype-v1';let saved;try{saved=JSON.parse(localStorage.getItem(STORE)||'{}')}catch{saved={}}let records=Array.isArray(saved.records)?saved.records:[],personal=saved.personal||null,current=null,mode='national',index=0;
const DEMO={income:5000,expense:3500,year:'演示年份（未选定）'}; // Layout-only values, never represented as official statistics.
const goods=[['大米','袋',65,'5千克／袋','rice'],['纯牛奶','盒',4,'250毫升／盒','milk'],['鸡蛋','盒',15,'10枚／盒','egg'],['苹果','袋',12,'1千克／袋','apple'],['面条','包',8,'500克／包','noodles'],['饮用水','瓶',2,'550毫升／瓶','water'],['洗衣液','瓶',30,'2千克／瓶','laundry'],['抽纸','包',5,'100抽／包','tissue']];
// Shared interaction state for the high-fidelity UI.
let screen='home', draftQuery='', searchState=null, returnScreen=null, modalFocus=null, queryTimer=0;
let exportAll=false, activeCardCount=10, lastHistoryMode=false;


function persist(){try{localStorage.setItem(STORE,JSON.stringify({records,personal}))}catch{toast('暂时无法保存，请稍后重试')}}

function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3200)}

function art(type='home'){const safe=['home','work','save','rice','milk','egg','apple','noodles','water','laundry','tissue'].includes(type)?type:'home';return `<img class="${type==='home'?'scene':'art'}" src="../ui/assets-panels/${safe}.svg" alt="" draggable="false">`;}

function home(){clearTimeout(queryTimer);mount(`<section class="home"><div class="eyebrow">把数字，放回生活里</div><h1>看看这笔钱，<br>是不是你认识的样子。</h1><p class="sub">当它变成上班的日子、餐桌上的饭菜，<br>你会不会，对它有不一样的感觉？</p>${art()}<form class="search" id="search"><input id="query" aria-label="金额、商品或服务" placeholder="输入金额、商品或服务" autocomplete="off" enterkeyhint="go" value="${esc(draftQuery)}"><button class="go" aria-label="开始比较">看看 ${uiIcon('arrow')}</button></form><div id="input-error" class="inline-error" role="alert"></div><div class="examples"><button class="chip" onclick="submitQuery('1万元')">¥ 1万元</button><button class="chip" onclick="submitQuery('手机')">一部手机</button><button class="chip" onclick="submitQuery('按摩')">一次按摩</button></div><div class="bottom-note">${uiIcon('shield')} 无需登录 · 历史记录保存在当前设备</div></section>`,'home');$('#search').onsubmit=e=>{e.preventDefault();submitQuery($('#query').value)};$('#query').oninput=()=>{draftQuery=$('#query').value;$('#input-error').textContent=''};}

function parseAmount(q){const m=q.replace(/[,，\s]/g,'').match(/^[¥￥]?(\d+(?:\.\d+)?)(万|亿)?(?:人民币|元)?$/);return m?Number(m[1])*(m[2]==='万'?1e4:m[2]==='亿'?1e8:1):null}

function submitQuery(q){q=q.trim();draftQuery=q;if(!q){$('#input-error').textContent='输入一笔金额，或你想了解的商品 / 服务';$('#query').focus();return}const amount=parseAmount(q);if(amount!==null){if(amount<=0||amount>1e12){$('#input-error').textContent='请输入大于0且不超过1万亿元的金额';return}start(amount,q,'用户输入金额');return}if(/^[¥￥+\-\d.,，\s万元亿人民币]+$/.test(q)){if($('#input-error'))$('#input-error').textContent='金额格式还没识别出来，可以试试“10000”或“1万元”';return}offers(q);}

function modal(title,body){modalFocus=document.activeElement;$('#overlay').innerHTML=`<div class="sheet-bg"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><div class="sheet-head"><h2>${esc(title)}</h2><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${body}</section></div>`;$('#overlay .sheet-bg').onclick=e=>{if(e.target.classList.contains('sheet-bg'))closeModal()};$('.phone').inert=true;$('#overlay .close').focus();}

function closeModal(){const had=!!$('#overlay').firstElementChild;$('#overlay').innerHTML='';$('.phone').inert=false;if(had&&modalFocus?.isConnected)modalFocus.focus();modalFocus=null;}

function offers(q,city='',chosen=-1){const service=/按摩|理发|美容|服务|健身/.test(q);searchState={q,city,chosen,service};if(service&&!city){mount(`<section class="flow"><button class="back" onclick="home()">${uiIcon('back')} 返回输入</button><div class="steps"><strong>补充城市</strong><span class="sep"></span><span>选择报价</span><span class="sep"></span><span>看看比较</span></div><h1>这次服务，<br>发生在哪座城市？</h1><p class="sub flow-lead">同一种服务，在不同地方有不同的价格。</p><div class="query-summary"><span>${esc(q)}</span><span class="tag">服务</span></div><form id="city-form"><label class="field">城市<input id="city" placeholder="例如：上海" autocomplete="address-level2" enterkeyhint="next"></label><div class="inline-error" id="city-error" role="alert"></div><button class="primary wide">继续选择报价 →</button></form><button class="link wide" id="city-manual">已经知道价格？直接填写</button></section>`,'offers');$('#city-form').onsubmit=e=>{e.preventDefault();const value=$('#city').value.trim();if(!value){$('#city-error').textContent='填写城市后，就能继续选择服务报价';$('#city').focus();return}offers(q,value)};$('#city-manual').onclick=()=>manual(q);return}
const prices=service?[199,299,399]:[3999,4999,5999];mount(`<section class="flow"><button class="back" onclick="home()">${uiIcon('back')} 返回输入</button><div class="steps"><strong>选择报价</strong><span class="sep"></span><span>看看比较</span></div><h1>选一个，<br>你想了解的价格。</h1><div class="query-summary"><span>${esc(q)}${city?' · '+esc(city):''}</span>${service?'<button class="link" id="change-city">更改城市</button>':'<span class="tag">中国大陆</span>'}</div><p class="quiet">选择适合的规格与报价</p><div id="offers" role="group" aria-label="商品或服务报价"></div><div class="flow-footer"><button class="primary wide" id="offer-next" ${chosen<0?'disabled':''}>${chosen<0?'先选择一个报价':'用 ¥'+money(prices[chosen])+' 开始比较 →'}</button><button class="link wide" id="manual">没有合适的？手动填写价格</button></div></section>`,'offers');if(service)$('#change-city').onclick=()=>offers(q);prices.forEach((price,i)=>{const option=service?['60分钟基础服务','90分钟标准服务','120分钟完整服务'][i]:['标准版 · 128GB','标准版 · 256GB','进阶版 · 256GB'][i];const b=document.createElement('button');b.className='offer'+(chosen===i?' selected':'');b.setAttribute('aria-pressed',String(chosen===i));b.innerHTML=`<strong>${esc(q)} · ${option}</strong><span class="tag">${service?['门店报价','预约报价','套餐报价'][i]:['品牌直营','平台自营','品牌专营'][i]}</span><span class="quiet">${city?' '+esc(city):''}</span><div class="price">¥ ${money(price)}</div>`;b.onclick=()=>{searchState.chosen=i;document.querySelectorAll('.offer').forEach((el,j)=>{el.classList.toggle('selected',i===j);el.setAttribute('aria-pressed',String(i===j))});$('#offer-next').disabled=false;$('#offer-next').textContent='用 ¥'+money(price)+' 开始比较 →'};$('#offers').append(b)});$('#offer-next').onclick=()=>{const i=searchState.chosen;if(i<0)return;const spec=service?['60分钟','90分钟','120分钟'][i]:['128GB','256GB','进阶版256GB'][i];start(prices[i],q+(city?' · '+city:''),(service?['门店报价','预约报价','套餐报价'][i]:['品牌直营','平台自营','品牌专营'][i])+' · '+spec)};$('#manual').onclick=()=>manual(q);}

function manual(q){mount(`<section class="flow"><button class="back" onclick="offers(searchState.q,searchState.city,searchState.chosen)">${uiIcon('back')} 返回选择报价</button><h1>用你知道的价格，<br>继续看看。</h1><p class="sub flow-lead">${esc(q)}${searchState?.city?' · '+esc(searchState.city):''}</p><form id="manual-form"><label class="field">人民币价格<input id="price" type="text" inputmode="decimal" placeholder="例如 299 或 1万元" enterkeyhint="go"></label><div class="inline-error" id="manual-error" role="alert"></div><div class="preview-box">这笔价格会标注为“用户输入价格”，<br>不会作为实时查询报价。</div><button class="primary wide">看看这笔钱 →</button></form></section>`,'manual');$('#manual-form').onsubmit=e=>{e.preventDefault();const a=parseAmount($('#price').value.trim());if(!(a>0&&a<=1e12)){$('#manual-error').textContent='请输入有效的正数价格，例如“299”或“1万元”';$('#price').focus();return}start(a,q+(searchState?.city?' · '+searchState.city:''),'用户输入价格')};}

function start(amount,label,source){clearTimeout(queryTimer);lastHistoryMode=false;mode='national';index=0;current={id:Date.now()+Math.random(),amount,label,source,date:new Date().toLocaleString('zh-CN'),baseline:{...DEMO},goods:goods.map(x=>[...x]),personal:personal?{...personal}:null};records.unshift(JSON.parse(JSON.stringify(current)));records=records.slice(0,100);persist();renderResult();}

function cards(){const base=mode==='personal'?current.personal:current.baseline;const income=base?.income||0,net=income-(base?.expense||0);function time(n){const value=n>=12?n/12:n,unit=n>=12?'年':'个月';return {num:value>0&&value<.1?'少于0.1':money(Math.round(value*10)/10),unit}}const t=time(current.amount/income),s=time(current.amount/net);return [{title:'赚取这笔钱',num:income>0?t.num:'无法估算',unit:income>0?t.unit:'',type:'work',caption:income>0?`按${mode==='personal'?'你填写的每月到手收入':'城镇私营单位就业人员平均工资'}计算，你需要不吃不喝工作${t.num.startsWith('少于')?'不足'+t.num.slice(2):'约 '+t.num} ${t.unit}来赚取这笔钱。`:'月收入为0，无法按收入估算赚取时间。'},{title:'存下这笔钱',num:net>0?s.num:'暂无结余',unit:net>0?s.unit:'',type:'save',caption:net>0?`按每月收入扣除生活开支后的结余计算，你需要积累${s.num.startsWith('少于')?'不足'+s.num.slice(2):'约 '+s.num} ${s.unit}才能存下这笔钱。`:'按当前收支，暂无可用于储蓄的结余。'},...current.goods.map(([name,unit,price,spec,type])=>({title:`可以买到 ${money(Math.floor(current.amount/price))} ${unit}${name}`,num:money(Math.floor(current.amount/price)),unit,type:({'面条':'noodles','饮用水':'water','洗衣液':'laundry','抽纸':'tissue'}[name]||type),caption:`按${spec}、参考单价 ¥${price}计算，${current.amount<price?'这笔钱还不足以购买一个完整单位的'+name+'。':'这笔钱约可以买到 '+money(Math.floor(current.amount/price))+' '+unit+name+'。'}`}))];}

function renderResult(){
  const data=cards();activeCardCount=data.length;index=Math.max(0,Math.min(index,data.length-1));
  mount(`<section class="result-minimal"><header class="minimal-toolbar"><button class="minimal-icon" onclick="flowBack()" aria-label="返回输入">${uiIcon('back')}</button><button class="minimal-amount" onclick="editAmount()" aria-label="修改金额">¥ ${money(current.amount)} ${uiIcon('edit')}</button><button class="minimal-icon" onclick="exportMenu()" aria-label="保存或分享">${uiIcon('share')}</button></header><div class="rail" tabindex="0" aria-label="比较卡片，左右滑动或使用方向键切换">${data.map((x,i)=>`<article class="card story-${esc(x.type)}" data-story="${esc(x.type)}" aria-label="第${i+1}张：${esc(x.title)}"><div class="card-top"><span>${i<2?'时间的刻度':'生活的刻度'}</span><span>${String(i+1).padStart(2,'0')} / ${data.length}</span></div><div class="card-context"><button onclick="modeMenu()" aria-label="切换比较基准">${mode==='national'?'全国参照':'个人情况'} ⌄</button></div><div class="number ${x.num.length>10?'is-long':x.num==='暂无结余'||x.num==='无法估算'||x.num.startsWith('少于')?'is-state':''}">${x.num}<small>${x.unit}</small></div><h2>${x.title}</h2>${art(x.type)}<div class="caption">${x.caption}</div><button class="source" onclick="details(${i})">查看计算依据 ↗</button>${lastHistoryMode?'<div class="minimal-history"><span>历史结果</span><button onclick="recalculate()">重新计算</button></div>':''}</article>`).join('')}</div><footer class="minimal-footer"><div class="dots">${data.map((_,i)=>`<button aria-label="查看第${i+1}张：${esc(data[i].title)}" class="dot ${index===i?'on':''}" onclick="goCard(${i})"></button>`).join('')}</div><span id="pos" class="sr-only" role="status" aria-live="polite"></span></footer></section>`,'result');initDeck(data);
}

function modeMenu(){modal('比较基准',`<div class="mode-options"><button class="${mode==='national'?'selected':''}" onclick="closeModal();setMode('national')"><span>全国参照</span><small>${mode==='national'?'当前使用':''}</small></button><button class="${mode==='personal'?'selected':''}" onclick="closeModal();setMode('personal')"><span>个人情况</span><small>${mode==='personal'?'当前使用':'按你的收入与开支'}</small></button></div>${personal||current.personal?'<button class="link wide" onclick="closeModal();editPersonal()">调整收入与开支</button>':''}`);}


function goCard(i){deckGo(i);}

function setMode(m){if(m===mode)return;if(m==='personal'&&!current.personal){editPersonal();return}mode=m;renderResult();}

function editPersonal(){const p=current?.personal||personal;mount(`<section class="flow"><button class="back" onclick="renderResult()">${uiIcon('back')} 返回比较</button><h1>换成你的生活节奏。</h1><p class="sub flow-lead">默认保存在当前设备，之后可以修改或清除。</p><form id="personal-form"><label class="field">每月到手收入（元）<input id="income" type="number" inputmode="decimal" min="0" step="any" value="${p?.income??''}" placeholder="例如 6000"></label><label class="field">每月生活开支（元）<input id="expense" type="number" inputmode="decimal" min="0" step="any" value="${p?.expense??''}" placeholder="例如 3500"></label><div class="preview-box" id="surplus-preview">填写两项，看看每月可以留下多少。</div><div class="inline-error" id="personal-error" role="alert"></div><button class="primary wide">查看个人情况 →</button></form><button class="link wide" onclick="confirmClearPersonal()">清除已保存的收支信息</button><p class="quiet">本次调整不会改变已保存的历史结果。</p></section>`,'personal');function preview(){const a=$('#income').value,b=$('#expense').value;if(a===''||b==='')return;const net=Number(a)-Number(b);$('#surplus-preview').textContent=net>0?'按当前收支，每月结余 ¥'+money(net):'按当前收支，暂无可用于储蓄的结余。'}$('#income').oninput=preview;$('#expense').oninput=preview;preview();$('#personal-form').onsubmit=e=>{e.preventDefault();const a=$('#income').value,b=$('#expense').value,income=Number(a),expense=Number(b);if(a===''||b===''||!Number.isFinite(income)||!Number.isFinite(expense)||income<0||expense<0){$('#personal-error').textContent='请填写有效的非负收入和开支';return}personal={income,expense};current.personal={...personal};persist();mode='personal';renderResult();};}

function clearPersonal(){personal=null;if(current)current.personal=null;persist();mode='national';closeModal();if(current)renderResult();toast('已清除收支信息');}

function details(i){let body;if(i<2){const b=mode==='personal'?current.personal:current.baseline;body=`${mode==='personal'?'根据你填写的到手收入与生活开支计算。':'根据当前收入与生活开支参照计算。'}\n每月收入：¥${money(b.income)}\n每月生活开支：¥${money(b.expense)}\n\n赚取时间（月）= 金额 ÷ 每月收入\n储蓄时间（月）= 金额 ÷ 每月结余\n每月结余 = 每月收入 − 每月生活开支\n\n结余不大于0时，不计算储蓄年限。\n按收入与开支保持不变估算，不包含投资收益、通胀或未来收支变化。`}else{const g=current.goods[i-2];body=`参照商品：${g[0]}\n规格：${g[3]}\n参考单价：¥${g[2]}\n\n可购买数量 = 金额 ÷ 参考单价\n按完整单位向下取整。\n\n价格会因地区、品牌与购买渠道有所不同；此处用于理解金额对应的购买力。`}modal('这张卡片如何计算',`<div class="details">${esc(body)}</div>`)}

function historyView(){if(screen!=='history')returnScreen=screen==='result'?'result':'home';mount(`<section class="flow"><button class="back" onclick="flowBack()">${uiIcon('back')} 返回${returnScreen==='result'?'比较':'首页'}</button><h1>再看看，曾经的比较。</h1><p class="sub flow-lead">记录当时的价格，也保留当时的视角。</p><div class="history-toolbar"><span class="count">本机记录 · ${records.length} 条</span>${records.length?'<button class="link" onclick="confirmClearHistory()">清空记录</button>':''}</div><div id="history-list"></div><p class="quiet">记录仅保存在当前设备。</p></section>`,'history');if(!records.length){$('#history-list').innerHTML=`<div class="empty">${art('save')}<p class="sub">还没有比较记录。<br>从一笔熟悉的金额开始吧。</p><button class="primary wide" onclick="home()">去看看一笔钱</button></div>`;return}records.forEach(r=>{const row=document.createElement('div');row.className='history-row';const open=document.createElement('button');open.innerHTML=`<strong>¥ ${money(r.amount)}</strong><small>${esc(r.label)}<br>${esc(r.date)}</small>`;open.onclick=()=>{current=JSON.parse(JSON.stringify(r));mode='national';index=0;lastHistoryMode=true;renderResult()};const del=document.createElement('button');del.className='delete-record';del.textContent='删除';del.setAttribute('aria-label','删除 '+r.label+' 的记录');del.onclick=()=>{const position=records.indexOf(r);records=records.filter(x=>x.id!==r.id);persist();historyView();undoToast(r,position)};row.append(open,del);$('#history-list').append(row)});}

function exportMenu(){exportAll=false;modal('把这个视角，留下来',`<div class="export-choice" role="group" aria-label="导出范围"><button class="selected" id="single-export" aria-pressed="true" onclick="chooseExport(false)">当前这一张</button><button id="all-export" aria-pressed="false" onclick="chooseExport(true)">全部 ${cards().length} 张</button></div><div id="export-preview"></div><div class="export-actions"><button class="secondary" onclick="exportImage(exportAll,false)">保存图片</button><button class="primary" onclick="exportImage(exportAll,true)">分享图片 ↗</button></div><p class="quiet">把这次比较保存下来，或分享给你想分享的人。</p>`);chooseExport(false);}

async function exportImage(all,share){try{const data=all?cards():[cards()[index]],w=750,h=all?180+data.length*210:650,canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#faf7ef';ctx.fillRect(0,0,w,h);ctx.fillStyle='#171717';ctx.font='bold 36px sans-serif';ctx.fillText('pomo · 生活里的另一种刻度',42,65);ctx.font='22px sans-serif';ctx.fillText('¥ '+money(current.amount)+' · '+(mode==='national'?'全国参照':'个人情况'),42,110);data.forEach((d,i)=>{const y=all?160+i*210:180;const panelHeight=all?190:350;ctx.fillStyle='#171717';ctx.fillRect(34,y+4,w-60,panelHeight);ctx.fillStyle=getComputedStyle(document.querySelectorAll('.card')[all?i:index]).backgroundColor;ctx.fillRect(30,y,w-60,panelHeight);ctx.strokeStyle='#171717';ctx.lineWidth=3;ctx.strokeRect(30,y,w-60,panelHeight);ctx.fillStyle='#171717';ctx.font='24px sans-serif';ctx.fillText(d.title,52,y+42);ctx.font='italic 900 50px Arial';ctx.fillText(d.num+' '+d.unit,52,y+108);ctx.font='19px sans-serif';ctx.fillText(d.caption,52,y+150,w-105);ctx.font='16px sans-serif';ctx.fillText('按当前收入、开支与参考单价计算',52,y+179)});ctx.fillStyle='#70617e';ctx.font='16px sans-serif';ctx.fillText('生成于 '+current.date,42,h-28);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error();const file=new File([blob],all?'pomo-全部卡片.png':'pomo-当前卡片.png',{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'pomo · 价值比较'})}else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(share?'已保存图片，可在相册或下载中分享':'图片已生成，请查看下载')} }catch(e){toast(e.name==='AbortError'?'已取消分享':'导出失败，请重试')}}

function mount(html,name){closeModal();screen=name;$('#view').innerHTML=html;$('#view').classList.remove('screen-enter');void $('#view').offsetWidth;$('#view').classList.add('screen-enter');window.scrollTo({top:0,behavior:'instant'});}

function flowBack(){if(screen==='result'){draftQuery=current.label;home()}else if(screen==='history'){returnScreen==='result'&&current?renderResult():home()}else if(screen==='manual'){searchState?offers(searchState.q,searchState.city):home()}else if(screen==='offers'){home()}else if(screen==='personal'){renderResult()}else home();}

function openOverview(){modal('这笔钱的10种表达',`<p class="quiet">点击任意一项，直接跳到对应卡片。</p>${cards().map((c,i)=>`<button class="offer" onclick="closeModal();goCard(${i})"><strong>${String(i+1).padStart(2,'0')} · ${esc(c.title)}</strong><span class="quiet">${c.num} ${c.unit}</span></button>`).join('')}`);}

function editAmount(){modal('换一笔金额看看',`<form id="amount-form"><label class="field">人民币金额<input id="new-amount" inputmode="decimal" value="${current.amount}" enterkeyhint="go"></label><div class="inline-error" id="amount-error" role="alert"></div><button class="primary wide">更新比较</button><button class="link wide" type="button" onclick="home()">改为查找商品或服务</button></form>`);$('#new-amount').focus();$('#new-amount').select();$('#amount-form').onsubmit=e=>{e.preventDefault();const amount=parseAmount($('#new-amount').value.trim());if(!(amount>0&&amount<=1e12)){$('#amount-error').textContent='请填写有效金额，例如“1万元”';return}start(amount,money(amount)+'元','用户输入金额')};}

function confirmClearPersonal(){modal('清除收支信息？','<p class="sub">清除后恢复全国参照，已有历史结果保持原样。</p><button class="primary wide" onclick="clearPersonal()">清除并返回全国参照</button><button class="secondary wide" onclick="closeModal()">保留收支信息</button>');}

function undoToast(record,position){clearTimeout(queryTimer);$('#toast').innerHTML='已删除记录 <button id="undo-delete" style="color:white;text-decoration:underline;pointer-events:auto;padding:8px">撤销</button>';$('#toast').hidden=false;$('#undo-delete').onclick=()=>{records.splice(position,0,record);persist();historyView();$('#toast').hidden=true};queryTimer=setTimeout(()=>$('#toast').hidden=true,5000);}

function confirmClearHistory(){modal('清空全部历史？','<p class="sub">清空后无法恢复。个人参数将保留。</p><button class="primary wide" id="confirm-clear">确认清空</button><button class="secondary wide" onclick="closeModal()">保留记录</button>');$('#confirm-clear').onclick=()=>{records=[];persist();closeModal();historyView();};}

function recalculate(){if(current.source==='用户输入金额'||current.source==='用户输入价格'){start(current.amount,current.label,current.source);toast('已重新计算，原记录保留')}else{offers(current.label);toast('重新选择报价后，将创建一条新记录')}}

function chooseExport(all){exportAll=all;$('#single-export').classList.toggle('selected',!all);$('#all-export').classList.toggle('selected',all);$('#single-export').setAttribute('aria-pressed',String(!all));$('#all-export').setAttribute('aria-pressed',String(all));const c=cards()[index];$('#export-preview').innerHTML=all?`<div class="export-preview"><div class="eyebrow">POMO · 全部比较合集</div><h3>¥ ${money(current.amount)} 的 ${cards().length} 种表达</h3><p class="quiet">赚取时间 · 储蓄时间 · 多种日常购买力</p><p class="quiet">全部比较，保存为一张长图</p></div>`:`<div class="export-preview"><div class="eyebrow">POMO · ${index+1} / ${cards().length}</div><h3>${c.title}</h3><b>${c.num} <small>${c.unit}</small></b><p class="quiet">${c.caption}</p><p class="quiet">包含比较结果与计算依据</p></div>`;}

document.addEventListener('keydown',e=>{
  const sheet=$('#overlay .sheet');
  if(e.key==='Escape'&&sheet){e.preventDefault();closeModal();return;}
  if(e.key==='Tab'&&sheet){
    const items=[...sheet.querySelectorAll('button:not(:disabled),input,a[href],[tabindex="0"]')];
    const first=items[0],last=items[items.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}
  }
});
$('.top .icon').innerHTML=uiIcon('history')+' 历史';
home();

function displaySource(value){return String(value).replace(/演示来源\s*(\d+)/g,'参考报价 $1');}
